#include "../wiegand.h"

void wiegand_instructions_scene_on_enter(void* context) {
    App* app = context;
    widget_reset(app->widget);
    widget_add_string_element(app->widget, 0, 0, AlignLeft, AlignTop, FontPrimary, "Instructions");
    widget_add_text_scroll_element(
        app->widget,
        0,
        13,
        128,
        51,
        "Wiegand Raw v" WIEGAND_VERSION "\n"
        "READ ONLY. Never transmits.\n"
        "Use only with permission.\n"
        "\n"
        "WIRING\n"
        "D0 (green) to pin A4\n"
        "D1 (white) to pin A7\n"
        "GND (black) to GND\n"
        "Tap in parallel. Do not\n"
        "cut the D0/D1 run.\n"
        "\n"
        "PROTECT THE FLIPPER\n"
        "Wiegand idles at 5V.\n"
        "On each data line use\n"
        "47k in series, then 82k\n"
        "from the pin to GND.\n"
        "Never touch reader power\n"
        "(red, 12V) to a pin.\n"
        "Run on battery, no USB.\n"
        "\n"
        "READING\n"
        "Idle should show D0:HI\n"
        "D1:HI. LO means no pull-\n"
        "up, no power, or a short.\n"
        "Any bit count is shown.\n"
        "\n"
        "CABLE TEST\n"
        "Badge ONE card 20 times.\n"
        "1st read is the reference.\n"
        "Bad = a read that differs.\n"
        "Compare Pulse at the\n"
        "reader end and the panel\n"
        "end with the same leads.\n"
        "\n"
        "TO RFID\n"
        "On a read, exports to the\n"
        "RFID app for its decoder.\n"
        "26-bit gives FC/card.\n"
        "27-43 bit: length+hex.\n"
        "48-bit+ cannot export.\n"
        "For analysis, not cloning.\n"
        "\n"
        "Captures are live\n"
        "credentials. Delete them\n"
        "when the job is done.\n");
    view_dispatcher_switch_to_view(app->view_dispatcher, WiegandWidgetView);
}
